// Workflow 14, JOB A (Welle 3, AP5): Portfoliorisiko-Pruefung + Paper-Trade-
// Anlage fuer heute von "06" neu geoeffnete Empfehlungen. Laeuft NACH "06" -
// Bestaetigung/DRY_RUN ist zu diesem Zeitpunkt bereits aufgeloest (siehe
// docs/PORTFOLIORISIKO.md fuer die Begruendung dieser Reihenfolge). Ein vom
// Portfoliorisiko blockierter Trade bekommt trotzdem eine paper_trades-Zeile
// (status='blocked') - vollstaendige Historie statt stillem Verwerfen.

function round(v, d = 4) { if (v === null || v === undefined || isNaN(v)) return null; return parseFloat(Number(v).toFixed(d)); }
function num(v) { const n = Number(v); return v === null || v === undefined || v === '' || isNaN(n) ? null : n; }

function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
}
const heute = getBusinessDate();
const run_id = 'p14-' + heute + '-' + Date.now();
const RISK_MODEL_VERSION = 'welle3-portfolio-v1';

const CFG = {};
for (const r of $('DB: Portfolio-Konfiguration laden').all().map(i => i.json)) CFG[r.config_key] = Number(r.value_numeric);
const MODEL_PORTFOLIO_VALUE = CFG.MODEL_PORTFOLIO_VALUE ?? 100000;
const MAX_TOTAL_OPEN_RISK_PCT = CFG.MAX_TOTAL_OPEN_RISK_PCT ?? 6.0;
const MAX_SECTOR_EXPOSURE_PCT = CFG.MAX_SECTOR_EXPOSURE_PCT ?? 15.0;
const MAX_SINGLE_POSITION_PCT = CFG.MAX_SINGLE_POSITION_PCT ?? 8.0;
const MAX_OPEN_POSITIONS = CFG.MAX_OPEN_POSITIONS ?? 10;
const MAX_DIRECTIONAL_EXPOSURE_PCT = CFG.MAX_DIRECTIONAL_EXPOSURE_PCT ?? 40.0;
const MAX_PORTFOLIO_DRAWDOWN_PCT = CFG.MAX_PORTFOLIO_DRAWDOWN_PCT ?? 15.0;
const CORRELATION_LOOKBACK_DAYS = CFG.CORRELATION_LOOKBACK_DAYS ?? 60;
const MAX_PAIRWISE_CORRELATION = CFG.MAX_PAIRWISE_CORRELATION ?? 0.75;
const STRESS_RISK_REDUCTION_FACTOR = CFG.STRESS_RISK_REDUCTION_FACTOR ?? 0.5;

const neueEmpfehlungen = $('DB: Heutige neue Empfehlungen laden').all().map(i => i.json);
const offenePaperTrades = $('DB: Offene Paper-Trades laden').all().map(i => i.json);
const geschlossenePaperTrades = $('DB: Geschlossene Paper-Trades laden (Drawdown)').all().map(i => i.json);
const regimeRows = $('DB: Marktregime laden (Portfolio)').all().map(i => i.json);
const priceRows = $('DB: Kursverlauf laden (Korrelation)').all().map(i => i.json);
const strategyStatusRows = $('DB: Strategie-Status laden').all().map(i => i.json);

const regimeByRegion = {}; for (const r of regimeRows) regimeByRegion[r.region] = r;
const strategyAktivByName = {}; for (const s of strategyStatusRows) strategyAktivByName[s.strategy] = s.aktiv === true || s.aktiv === 'true';

const priceByTicker = {};
for (const p of priceRows) { const k = String(p.symbol || '').trim(); if (!priceByTicker[k]) priceByTicker[k] = []; priceByTicker[k].push(p); }
for (const k of Object.keys(priceByTicker)) priceByTicker[k].sort((a, b) => String(a.trading_date).localeCompare(String(b.trading_date)));
function dailyReturns(ticker) {
  const rows = (priceByTicker[ticker] || []).slice(-(CORRELATION_LOOKBACK_DAYS + 1));
  const closes = rows.map(r => Number(r.close)).filter(v => !isNaN(v));
  const rets = [];
  for (let i = 1; i < closes.length; i++) if (closes[i - 1] > 0) rets.push((closes[i] - closes[i - 1]) / closes[i - 1]);
  return rets;
}
function pearson(a, b) {
  const n = Math.min(a.length, b.length);
  if (n < 10) return null;
  const av = a.slice(-n), bv = b.slice(-n);
  const meanA = av.reduce((x, y) => x + y, 0) / n, meanB = bv.reduce((x, y) => x + y, 0) / n;
  let cov = 0, varA = 0, varB = 0;
  for (let i = 0; i < n; i++) { cov += (av[i] - meanA) * (bv[i] - meanB); varA += (av[i] - meanA) ** 2; varB += (bv[i] - meanB) ** 2; }
  if (varA === 0 || varB === 0) return null;
  return cov / Math.sqrt(varA * varB);
}

// Realisierter Drawdown seit Systemstart (aus geschlossenen Trades, chronologisch)
geschlossenePaperTrades.sort((a, b) => String(a.exit_time).localeCompare(String(b.exit_time)));
let equity = 0, peak = 0, maxDrawdownPct = 0;
for (const t of geschlossenePaperTrades) {
  equity += Number(t.net_pnl) || 0;
  if (equity > peak) peak = equity;
  const dd = peak > 0 ? ((peak - equity) / MODEL_PORTFOLIO_VALUE) * 100 : 0;
  if (dd > maxDrawdownPct) maxDrawdownPct = dd;
}
const aktuellerDrawdownPct = peak > 0 ? ((peak - equity) / MODEL_PORTFOLIO_VALUE) * 100 : 0;

function offeneSumme(feld, filterFn) {
  return offenePaperTrades.filter(filterFn || (() => true)).reduce((sum, t) => sum + (Number(t[feld]) || 0), 0);
}

const output = [];
for (const empf of neueEmpfehlungen) {
  const ticker = empf.ticker;
  const region = empf.market_regime_region || 'Europa';
  const regime = regimeByRegion[region] || null;
  const istStress = regime && regime.combined_regime === 'stress';

  const blockers = [];

  // Strategie global deaktiviert? (AP9-Aktivierungspfad)
  if (empf.strategy && strategyAktivByName[empf.strategy] === false) {
    blockers.push({ code: 'STRATEGY_DEACTIVATED', message: 'Strategie ' + empf.strategy + ' ist ueber einen aktivierten Lernvorschlag global deaktiviert.' });
  }

  const risikoVorher = offeneSumme('risk_amount');
  const risikoDanach = risikoVorher + (Number(empf.risk_amount) || 0);
  const portfolioRiskBefore = round(risikoVorher / MODEL_PORTFOLIO_VALUE, 5);
  const portfolioRiskAfter = round(risikoDanach / MODEL_PORTFOLIO_VALUE, 5);
  const effectiveMaxTotalRiskPct = istStress ? MAX_TOTAL_OPEN_RISK_PCT * STRESS_RISK_REDUCTION_FACTOR : MAX_TOTAL_OPEN_RISK_PCT;
  if (portfolioRiskAfter * 100 > effectiveMaxTotalRiskPct) {
    blockers.push({ code: 'TOTAL_RISK_LIMIT', message: 'Gesamtes offenes Stoprisiko wuerde ' + (portfolioRiskAfter * 100).toFixed(2) + '% uebersteigen (Limit ' + effectiveMaxTotalRiskPct.toFixed(2) + '%' + (istStress ? ', stressreduziert' : '') + ')' });
  }

  const sektorWert = offeneSumme('position_value', t => t.sektor === empf.sektor) + (Number(empf.position_value) || 0);
  if ((sektorWert / MODEL_PORTFOLIO_VALUE) * 100 > MAX_SECTOR_EXPOSURE_PCT) {
    blockers.push({ code: 'SECTOR_LIMIT', message: 'Sektor ' + empf.sektor + ' ueberschreitet das konfigurierte Limit (' + MAX_SECTOR_EXPOSURE_PCT + '%)' });
  }

  const einzelAnteilPct = ((Number(empf.position_value) || 0) / MODEL_PORTFOLIO_VALUE) * 100;
  if (einzelAnteilPct > MAX_SINGLE_POSITION_PCT) {
    blockers.push({ code: 'SINGLE_POSITION_LIMIT', message: 'Einzelposition ' + einzelAnteilPct.toFixed(2) + '% ueberschreitet das Limit (' + MAX_SINGLE_POSITION_PCT + '%)' });
  }

  if (offenePaperTrades.length + 1 > MAX_OPEN_POSITIONS) {
    blockers.push({ code: 'MAX_OPEN_POSITIONS', message: 'Maximale Anzahl offener Positionen (' + MAX_OPEN_POSITIONS + ') bereits erreicht' });
  }

  const richtungWert = offeneSumme('position_value', t => t.direction === empf.richtung || t.direction === (empf.richtung === 'kauf' ? 'long' : 'short')) + (Number(empf.position_value) || 0);
  if ((richtungWert / MODEL_PORTFOLIO_VALUE) * 100 > MAX_DIRECTIONAL_EXPOSURE_PCT) {
    blockers.push({ code: 'DIRECTIONAL_LIMIT', message: 'Richtungs-Exposition ueberschreitet das Limit (' + MAX_DIRECTIONAL_EXPOSURE_PCT + '%)' });
  }

  if (aktuellerDrawdownPct > MAX_PORTFOLIO_DRAWDOWN_PCT) {
    blockers.push({ code: 'DRAWDOWN_LIMIT', message: 'Aktueller Portfolio-Drawdown (' + aktuellerDrawdownPct.toFixed(2) + '%) ueberschreitet das Limit (' + MAX_PORTFOLIO_DRAWDOWN_PCT + '%) - keine neuen Eroeffnungen' });
  }

  const candReturns = dailyReturns(ticker);
  let maxCorr = null, maxCorrTicker = null;
  for (const t of offenePaperTrades) {
    if (t.ticker === ticker) continue;
    const otherReturns = dailyReturns(t.ticker);
    const corr = pearson(candReturns, otherReturns);
    if (corr !== null && (maxCorr === null || Math.abs(corr) > Math.abs(maxCorr))) { maxCorr = corr; maxCorrTicker = t.ticker; }
  }
  if (maxCorr !== null && Math.abs(maxCorr) > MAX_PAIRWISE_CORRELATION) {
    blockers.push({ code: 'CORRELATION_LIMIT', message: 'Hohe Korrelation (' + maxCorr.toFixed(2) + ') zu bereits offener Position ' + maxCorrTicker });
  }

  const approved = blockers.length === 0;
  output.push({
    _typ: 'portfolio_check',
    run_id, ticker, portfolio_approved: approved,
    portfolio_risk_before: portfolioRiskBefore, portfolio_risk_after: portfolioRiskAfter,
    blockers, config_snapshot: CFG, risk_model_version: RISK_MODEL_VERSION
  });

  const tradeId = ticker + '-' + heute + '-' + empf.strategy;
  output.push({
    _typ: 'paper_trade_create',
    trade_id: tradeId, run_id, recommendation_id: empf.id, ticker, strategy: empf.strategy || 'unbekannt',
    direction: empf.richtung === 'kauf' ? 'long' : 'short',
    signal_created_at: empf.thesis_created_at || empf.letzte_aktualisierung, decision_time: empf.letzte_aktualisierung,
    entry_rule: 'zone_touch_conservative', planned_entry_zone_low: empf.entry_zone_low, planned_entry_zone_high: empf.entry_zone_high,
    stop_price_initial: empf.stop_price, target_price_initial: empf.target_price,
    time_stop_at: empf.time_stop_at, thesis_expires_at: empf.thesis_expires_at,
    theoretical_quantity: empf.theoretical_quantity, risk_amount: empf.risk_amount, position_value: empf.position_value,
    market_regime_at_entry: empf.combined_regime, opportunity_score_at_entry: empf.opportunity_score,
    risk_score_at_entry: empf.risk_score, evidence_confidence_at_entry: empf.evidence_confidence,
    configuration_version: JSON.stringify(empf.configuration_snapshot_json || {}).slice(0, 200),
    rule_version: empf.thesis_rule_version, execution_model_version: 'welle3-exec-v1', risk_model_version: RISK_MODEL_VERSION,
    status: approved ? 'proposed' : 'blocked', sektor: empf.sektor
  });
}

return output.map(o => ({ json: o }));

// Workflow 14: ein gemeinsamer SQL-Dispatcher fuer alle Ausgabe-Item-Typen aus
// Job A (Portfoliopruefung/Trade-Anlage) und Job B (Ausfuehrung/Exit). Ein
// Dispatcher statt vieler einzelner SQL-bauen-Nodes haelt den Workflow-Graphen
// uebersichtlich - jeder Zweig ist unten als eigene, benannte Funktion klar
// abgegrenzt.

function pgStr(v) { return v === null || v === undefined || v === '' ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { if (v === true) return 'TRUE'; if (v === false) return 'FALSE'; return 'NULL'; }
function pgJsonb(v) { return (v === null || v === undefined) ? "'{}'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

const j = $json;
let sql = 'SELECT 1;';

if (j._typ === 'portfolio_check') {
  sql = `INSERT INTO trading.portfolio_risk_checks
    (run_id, ticker, portfolio_approved, portfolio_risk_before, portfolio_risk_after, blockers_json, config_snapshot_json, risk_model_version)
    VALUES (${pgStr(j.run_id)}, ${pgStr(j.ticker)}, ${pgBool(j.portfolio_approved)}, ${pgNum(j.portfolio_risk_before)}, ${pgNum(j.portfolio_risk_after)}, ${pgJsonb(j.blockers)}, ${pgJsonb(j.config_snapshot)}, ${pgStr(j.risk_model_version)});`;
}

else if (j._typ === 'paper_trade_create') {
  sql = `INSERT INTO trading.paper_trades
    (trade_id, run_id, recommendation_id, ticker, strategy, direction, signal_created_at, decision_time, entry_rule,
     planned_entry_zone_low, planned_entry_zone_high, stop_price_initial, target_price_initial, stop_price_current,
     time_stop_at, thesis_expires_at, theoretical_quantity, risk_amount, position_value, market_regime_at_entry,
     opportunity_score_at_entry, risk_score_at_entry, evidence_confidence_at_entry, configuration_version, rule_version,
     execution_model_version, risk_model_version, status)
    VALUES (${pgStr(j.trade_id)}, ${pgStr(j.run_id)}, ${pgNum(j.recommendation_id)}, ${pgStr(j.ticker)}, ${pgStr(j.strategy)}, ${pgStr(j.direction)},
      ${pgStr(j.signal_created_at)}, ${pgStr(j.decision_time)}, ${pgStr(j.entry_rule)},
      ${pgNum(j.planned_entry_zone_low)}, ${pgNum(j.planned_entry_zone_high)}, ${pgNum(j.stop_price_initial)}, ${pgNum(j.target_price_initial)}, ${pgNum(j.stop_price_initial)},
      ${pgStr(j.time_stop_at)}, ${pgStr(j.thesis_expires_at)}, ${pgNum(j.theoretical_quantity)}, ${pgNum(j.risk_amount)}, ${pgNum(j.position_value)}, ${pgStr(j.market_regime_at_entry)},
      ${pgNum(j.opportunity_score_at_entry)}, ${pgNum(j.risk_score_at_entry)}, ${pgNum(j.evidence_confidence_at_entry)}, ${pgStr(j.configuration_version)}, ${pgStr(j.rule_version)},
      ${pgStr(j.execution_model_version)}, ${pgStr(j.risk_model_version)}, ${pgStr(j.status)})
    ON CONFLICT (trade_id) DO NOTHING;`;
}

else if (j._typ === 'event') {
  sql = `INSERT INTO trading.paper_trade_events (trade_id, event_type, old_status, new_status, details_json)
    VALUES (${pgStr(j.trade_id)}, ${pgStr(j.event_type)}, ${pgStr(j.old_status)}, ${pgStr(j.new_status)}, ${pgJsonb(j.details)});`;
}

else if (j._typ === 'trade_fill') {
  sql = `UPDATE trading.paper_trades SET
    status = ${pgStr(j.status)}, simulated_entry_time = ${pgStr(j.simulated_entry_time)}, simulated_entry_price = ${pgNum(j.simulated_entry_price)},
    stop_price_current = ${pgNum(j.stop_price_current)}, ambiguous_execution = ${pgBool(j.ambiguous_execution)}, updated_at = now()
    WHERE trade_id = ${pgStr(j.trade_id)} AND status = 'proposed';`;
}

else if (j._typ === 'trade_close_unfilled') {
  sql = `UPDATE trading.paper_trades SET status = 'expired_unfilled', updated_at = now() WHERE trade_id = ${pgStr(j.trade_id)} AND status = 'proposed';`;
}

else if (j._typ === 'trade_flag') {
  sql = `UPDATE trading.paper_trades SET status = ${pgStr(j.status)}, data_quality_at_exit = ${pgStr(j.data_quality_at_exit)}, updated_at = now() WHERE trade_id = ${pgStr(j.trade_id)};`;
}

else if (j._typ === 'cost') {
  sql = `INSERT INTO trading.paper_trade_costs (trade_id, cost_type, amount, model_name)
    VALUES (${pgStr(j.trade_id)}, ${pgStr(j.cost_type)}, ${pgNum(j.amount)}, ${pgStr(j.model_name)});`;
}

else if (j._typ === 'valuation') {
  sql = `INSERT INTO trading.paper_trade_valuations (trade_id, valuation_date, mark_price, maximum_favorable_excursion, maximum_adverse_excursion)
    VALUES (${pgStr(j.trade_id)}, ${pgStr(j.valuation_date)}, ${pgNum(j.mark_price)}, ${pgNum(j.mfe_today)}, ${pgNum(j.mae_today)})
    ON CONFLICT (trade_id, valuation_date) DO UPDATE SET
      mark_price = EXCLUDED.mark_price,
      maximum_favorable_excursion = GREATEST(COALESCE(trading.paper_trade_valuations.maximum_favorable_excursion, 0), EXCLUDED.maximum_favorable_excursion),
      maximum_adverse_excursion = GREATEST(COALESCE(trading.paper_trade_valuations.maximum_adverse_excursion, 0), EXCLUDED.maximum_adverse_excursion);
    UPDATE trading.paper_trades SET
      maximum_favorable_excursion = GREATEST(COALESCE(maximum_favorable_excursion, 0), ${pgNum(j.mfe_today)}),
      maximum_adverse_excursion = GREATEST(COALESCE(maximum_adverse_excursion, 0), ${pgNum(j.mae_today)}),
      updated_at = now()
    WHERE trade_id = ${pgStr(j.trade_id)};`;
}

else if (j._typ === 'trade_close') {
  sql = `UPDATE trading.paper_trades SET
    status = 'closed', exit_time = ${pgStr(j.exit_time)}, exit_price = ${pgNum(j.exit_price)}, exit_reason = ${pgStr(j.exit_reason)},
    exit_reasons_all_json = ${pgJsonb(j.exit_reasons_all)}, gross_pnl = ${pgNum(j.gross_pnl)}, net_pnl = ${pgNum(j.net_pnl)},
    return_pct = ${pgNum(j.return_pct)}, realized_r_multiple = ${pgNum(j.realized_r_multiple)}, holding_period_days = ${pgNum(j.holding_period_days)},
    ambiguous_execution = ${pgBool(j.ambiguous_execution)}, data_quality_at_exit = ${pgStr(j.data_quality_at_exit)}, updated_at = now()
    WHERE trade_id = ${pgStr(j.trade_id)} AND status = 'open';`;
}

else if (j._typ === 'stress_scenario') {
  sql = `INSERT INTO trading.stress_scenarios (run_id, scenario_name, assumptions_json, affected_positions_json, estimated_loss, loss_pct_of_portfolio, data_quality, model_version)
    VALUES (${pgStr(j.run_id)}, ${pgStr(j.scenario_name)}, ${pgJsonb(j.assumptions)}, ${pgJsonb(j.affected_positions)}, ${pgNum(j.estimated_loss)}, ${pgNum(j.loss_pct_of_portfolio)}, ${pgStr(j.data_quality)}, ${pgStr(j.model_version)});`;
}

return { json: { ...j, sql } };

// Workflow 14, JOB B (Welle 3, AP2+AP3+AP4): taegliche Ausfuehrungs-/Exit-
// Simulation fuer bestehende Paper Trades. Konservativ und deterministisch
// (Auftragsvorgabe) - siehe docs/AUSFUEHRUNGSMODELL.md fuer jede Annahme.
// Nutzt AUSSCHLIESSLICH Tageskerzen (open/high/low/close aus
// trading.stock_price_history, Welle 1) - keine Intraday-Daten vorhanden,
// AMBIGUOUS_BAR_POLICY regelt den Fall "Stop und Ziel in derselben Kerze".

function round(v, d = 4) { if (v === null || v === undefined || isNaN(v)) return null; return parseFloat(Number(v).toFixed(d)); }
function num(v) { const n = Number(v); return v === null || v === undefined || v === '' || isNaN(n) ? null : n; }

const CFG = {};
for (const r of $('DB: Portfolio-Konfiguration laden (Exec)').all().map(i => i.json)) CFG[r.config_key] = Number(r.value_numeric);
const FEE_BPS = CFG.DEFAULT_FEES_BPS ?? 15;
const SLIPPAGE_BPS = CFG.DEFAULT_SLIPPAGE_BPS ?? 10;
const AMBIGUOUS_BAR_POLICY = 'conservative_stop_first'; // konfigurierbar dokumentiert (docs/AUSFUEHRUNGSMODELL.md), aktuell einziges implementiertes Modell
const EXECUTION_MODEL_VERSION = 'welle3-exec-v1';

const trades = $('DB: Ausstehende/offene Paper-Trades laden').all().map(i => i.json);
const barsRows = $('DB: Heutige Kerzen laden (Exec)').all().map(i => i.json);
const strategyRows = $('DB: Strategiesignale heute laden (Exec)').all().map(i => i.json);

const barByTicker = {}; for (const b of barsRows) barByTicker[String(b.symbol || '').trim()] = b;
const strategyByTicker = {};
for (const s of strategyRows) { const k = String(s.ticker || '').trim(); if (!strategyByTicker[k]) strategyByTicker[k] = []; strategyByTicker[k].push(s); }

function fee(value) { return round(value * (FEE_BPS / 10000), 2); }
function slippage(value) { return round(value * (SLIPPAGE_BPS / 10000), 2); }

const output = [];
const now = new Date();

for (const t of trades) {
  const bar = barByTicker[t.ticker];
  const events = [];

  if (!bar || bar.open == null || bar.high == null || bar.low == null || bar.close == null) {
    if (t.status === 'open') {
      // Datenfehler bei einem offenen Trade -> manueller Pruefpfad, NICHT automatisch schliessen.
      output.push({ json: { _typ: 'trade_flag', trade_id: t.trade_id, status: 'data_error', data_quality_at_exit: 'invalid' } });
      events.push({ trade_id: t.trade_id, event_type: 'data_error_flagged', old_status: t.status, new_status: t.status, details: { reason: 'keine gueltige Tageskerze heute' } });
    }
    for (const e of events) output.push({ json: { _typ: 'event', ...e } });
    continue;
  }

  const open = num(bar.open), high = num(bar.high), low = num(bar.low), close = num(bar.close);
  const richtungLong = t.direction === 'long';

  // ------------------------------------------------------------
  // Status 'proposed' -> pruefen ob die Einstiegszone erreicht wurde
  // (AP2: ENTRY_EXECUTION_MODEL='zone_touch_conservative')
  // ------------------------------------------------------------
  if (t.status === 'proposed') {
    const zoneLow = num(t.planned_entry_zone_low), zoneHigh = num(t.planned_entry_zone_high);
    let gefuellt = false, fillPrice = null, ambiguous = false;
    if (zoneLow !== null && zoneHigh !== null) {
      const beruehrt = low <= zoneHigh && high >= zoneLow;
      if (beruehrt) {
        gefuellt = true;
        if (open >= zoneLow && open <= zoneHigh) {
          fillPrice = open; // Eroeffnung bereits in der Zone - realistischer Fuellkurs
        } else if (open < zoneLow) {
          // Gap unter die Zone (fuer Long guenstiger als geplant) - konservativ NICHT den
          // guenstigeren Kurs annehmen, sondern den Zonenrand (kein rueckwirkend optimaler Kurs).
          fillPrice = zoneLow;
        } else {
          // Eroeffnung ueber der Zone, aber im Tagesverlauf zurueck in die Zone gelaufen -
          // konservativ der fuer den Trade schlechteste Punkt der Zone.
          fillPrice = richtungLong ? zoneHigh : zoneLow;
          ambiguous = true; // aus Tageskerzen nicht rekonstruierbar, WANN exakt beruehrt wurde
        }
      }
    }
    if (gefuellt) {
      const entryFee = fee(fillPrice * t.theoretical_quantity);
      const entrySlippage = slippage(fillPrice * t.theoretical_quantity);
      output.push({ json: { _typ: 'trade_fill', trade_id: t.trade_id, status: 'open', simulated_entry_time: now.toISOString(), simulated_entry_price: fillPrice, stop_price_current: t.stop_price_initial, ambiguous_execution: ambiguous } });
      output.push({ json: { _typ: 'cost', trade_id: t.trade_id, cost_type: 'entry_fee', amount: entryFee, model_name: 'fee_bps_v1' } });
      output.push({ json: { _typ: 'cost', trade_id: t.trade_id, cost_type: 'entry_slippage', amount: entrySlippage, model_name: 'slippage_bps_v1' } });
      output.push({ json: { _typ: 'event', trade_id: t.trade_id, event_type: 'filled', old_status: 'proposed', new_status: 'open', details: { fillPrice, ambiguous } } });
    } else {
      // Nicht erreicht - Ablauf pruefen (Zeitstop oder Thesenablauf ohne Fuellung)
      const abgelaufen = (t.time_stop_at && new Date(t.time_stop_at) <= now) || (t.thesis_expires_at && new Date(t.thesis_expires_at) <= now);
      if (abgelaufen) {
        output.push({ json: { _typ: 'trade_close_unfilled', trade_id: t.trade_id, status: 'expired_unfilled' } });
        output.push({ json: { _typ: 'event', trade_id: t.trade_id, event_type: 'expired_unfilled', old_status: 'proposed', new_status: 'expired_unfilled', details: {} } });
      }
    }
    continue;
  }

  // ------------------------------------------------------------
  // Status 'open' -> Exit-Engine
  // ------------------------------------------------------------
  if (t.status === 'open') {
    const entry = num(t.simulated_entry_price);
    const stop = num(t.stop_price_current || t.stop_price_initial);
    const target = num(t.target_price_initial);
    const qty = num(t.theoretical_quantity) || 0;

    // MFE/MAE dieser Kerze
    const favorable = richtungLong ? high - entry : entry - low;
    const adverse = richtungLong ? entry - low : high - entry;
    output.push({ json: { _typ: 'valuation', trade_id: t.trade_id, valuation_date: bar.trading_date, mark_price: close, mfe_today: round(favorable, 4), mae_today: round(adverse, 4) } });

    const stopBeruehrt = richtungLong ? low <= stop : high >= stop;
    const targetBeruehrt = richtungLong ? high >= target : low <= target;
    const exitReasonsAll = [];
    let exitReason = null, exitPrice = null, ambiguous = false;

    if (stopBeruehrt && targetBeruehrt) {
      ambiguous = true;
      exitReasonsAll.push('stop_loss', 'target_reached', 'ambiguous_execution');
      if (AMBIGUOUS_BAR_POLICY === 'conservative_stop_first') { exitReason = 'stop_loss'; exitPrice = stop; }
    } else if (stopBeruehrt) {
      exitReason = 'stop_loss'; exitPrice = stop; exitReasonsAll.push('stop_loss');
    } else if (targetBeruehrt) {
      exitReason = 'target_reached'; exitPrice = target; exitReasonsAll.push('target_reached');
    }

    if (!exitReason && t.time_stop_at && new Date(t.time_stop_at) <= now) { exitReason = 'time_stop'; exitPrice = close; exitReasonsAll.push('time_stop'); }
    if (!exitReason && t.thesis_expires_at && new Date(t.thesis_expires_at) <= now) { exitReason = 'thesis_expired'; exitPrice = close; exitReasonsAll.push('thesis_expired'); }
    if (!exitReason) {
      const strat = (strategyByTicker[t.ticker] || []).find(s => s.strategy === t.strategy);
      if (strat) {
        const stratDirection = strat.direction === 'long' ? 'long' : (strat.direction === 'short' ? 'short' : 'neutral');
        if (stratDirection !== 'neutral' && stratDirection !== t.direction) { exitReason = 'opposite_signal'; exitPrice = close; exitReasonsAll.push('opposite_signal'); }
      }
    }

    if (exitReason) {
      const grossPnl = richtungLong ? (exitPrice - entry) * qty : (entry - exitPrice) * qty;
      const exitFee = fee(exitPrice * qty);
      const exitSlippage = slippage(exitPrice * qty);
      const netPnl = round(grossPnl - exitFee - exitSlippage, 2);
      const returnPct = entry > 0 ? round((netPnl / (entry * qty)) * 100, 3) : null;
      const riskAmount = num(t.risk_amount);
      const rMultiple = riskAmount && riskAmount > 0 ? round(netPnl / riskAmount, 3) : null;
      const holdingDays = t.simulated_entry_time ? round((now.getTime() - new Date(t.simulated_entry_time).getTime()) / 86400000, 2) : null;

      output.push({ json: { _typ: 'trade_close', trade_id: t.trade_id, status: 'closed', exit_time: now.toISOString(), exit_price: exitPrice, exit_reason: exitReason, exit_reasons_all: exitReasonsAll, gross_pnl: round(grossPnl, 2), net_pnl: netPnl, return_pct: returnPct, realized_r_multiple: rMultiple, holding_period_days: holdingDays, ambiguous_execution: ambiguous, data_quality_at_exit: bar.data_quality_status || 'valid' } });
      output.push({ json: { _typ: 'cost', trade_id: t.trade_id, cost_type: 'exit_fee', amount: exitFee, model_name: 'fee_bps_v1' } });
      output.push({ json: { _typ: 'cost', trade_id: t.trade_id, cost_type: 'exit_slippage', amount: exitSlippage, model_name: 'slippage_bps_v1' } });
      output.push({ json: { _typ: 'event', trade_id: t.trade_id, event_type: 'closed', old_status: 'open', new_status: 'closed', details: { exitReason, exitReasonsAll, ambiguous } } });
    }
  }
}

return output;

