// Workflow 14, JOB C (Welle 3, AP6): einfache, transparente Stressszenarien.
// Bewusst simple Annahmen statt eines vorgetaeuschten komplexen Modells
// (Auftragsvorgabe) - jede Annahme ist unten im Code benannt und in
// docs/PORTFOLIORISIKO.md dokumentiert.

function round(v, d = 2) { if (v === null || v === undefined || isNaN(v)) return null; return parseFloat(Number(v).toFixed(d)); }
function num(v) { const n = Number(v); return v === null || v === undefined || v === '' || isNaN(n) ? null : n; }
function getBusinessDate(date = new Date()) { return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date); }

const CFG = {};
for (const r of $('DB: Portfolio-Konfiguration laden (Stress)').all().map(i => i.json)) CFG[r.config_key] = Number(r.value_numeric);
const MODEL_PORTFOLIO_VALUE = CFG.MODEL_PORTFOLIO_VALUE ?? 100000;
const MODEL_VERSION = 'welle3-stress-v1';
const run_id = 'stress-' + getBusinessDate() + '-' + Date.now();

const offenePositionen = $('DB: Offene Paper-Trades laden (Stress)').all().map(i => i.json);
const dataQuality = offenePositionen.length > 0 ? 'valid' : 'limited';

// Annahme: die Aktie bewegt sich 1:1 mit dem angenommenen Index-/Sektor-Schock
// (kein echtes Beta pro Ticker verfuegbar - konservative, transparent benannte
// Vereinfachung, siehe docs/PORTFOLIORISIKO.md). Fuer Short-Positionen wird ein
// negativer Marktschock zum Gewinn, daher hier als Verlust gedeckelt auf 0.
function position_value_loss(pos, pctMove) { return num(pos.position_value) * (pctMove / 100); }

function scenario(name, assumptions, computeFn) {
  let totalLoss = 0;
  const affected = [];
  for (const pos of offenePositionen) {
    const loss = computeFn(pos);
    if (loss !== 0) { totalLoss += loss; affected.push({ ticker: pos.ticker, direction: pos.direction, loss: round(loss, 2) }); }
  }
  return { _typ: 'stress_scenario', run_id, scenario_name: name, assumptions, affected_positions: affected, estimated_loss: round(totalLoss, 2), loss_pct_of_portfolio: round((totalLoss / MODEL_PORTFOLIO_VALUE) * 100, 3), data_quality: dataQuality, model_version: MODEL_VERSION };
}

const output = [];

output.push(scenario('referenzindex_minus_3pct', 'Alle Positionen bewegen sich 1:1 mit einem angenommenen -3% Indexschock (kein Einzel-Beta verfuegbar).', pos => pos.direction === 'long' ? position_value_loss(pos, -3) : -Math.max(0, position_value_loss(pos, -3))));
output.push(scenario('referenzindex_minus_5pct', 'Wie oben, -5% Indexschock.', pos => pos.direction === 'long' ? position_value_loss(pos, -5) : -Math.max(0, position_value_loss(pos, -5))));
output.push(scenario('referenzindex_minus_10pct', 'Wie oben, -10% Indexschock.', pos => pos.direction === 'long' ? position_value_loss(pos, -10) : -Math.max(0, position_value_loss(pos, -10))));

output.push(scenario('sektor_minus_7pct', 'Alle Positionen bewegen sich 1:1 mit einem -7% Sektorschock, unabhaengig vom tatsaechlichen Sektor jeder einzelnen Position (vereinfachend auf alle offenen Positionen angewendet, da kein sektor-spezifischer Index im Datenuniversum verfuegbar ist).', pos => pos.direction === 'long' ? position_value_loss(pos, -7) : -Math.max(0, position_value_loss(pos, -7))));

output.push(scenario('waehrungsschock', 'Alle Bestandsticker sind EUR-denominiert (XETRA) - ein EUR/USD-Schock hat auf das aktuelle Datenuniversum keine direkte Wirkung. Schema/Berechnung vorbereitet fuer kuenftige nicht-EUR-Positionen.', pos => 0));

output.push(scenario('volatilitaetssprung', 'Angenommene Verdopplung der Tagesvolatilitaet fuehrt zu einer zusaetzlichen ungeplanten Bewegung von einer weiteren geplanten Stop-Distanz gegen die Position (grobe, transparent benannte Naeherung ohne Options-/Vega-Modell).', pos => {
  const stopDist = Math.abs(num(pos.simulated_entry_price || pos.stop_price_initial) - num(pos.stop_price_initial));
  const qty = num(pos.theoretical_quantity) || 0;
  return -1 * stopDist * qty;
}));

output.push(scenario('gap_durch_stop', 'Jede offene Position gapt beim Stop um eine weitere Stop-Distanz durch (realistisches Gap-Risiko bei Tageskerzen ohne garantierte Ausfuehrung exakt am Stop).', pos => {
  const stopDist = Math.abs(num(pos.simulated_entry_price || pos.stop_price_initial) - num(pos.stop_price_initial));
  const qty = num(pos.theoretical_quantity) || 0;
  return -1 * stopDist * qty;
}));

output.push({ _typ: 'stress_scenario', run_id, scenario_name: 'gleichzeitige_mehrfach_stopausloesung', assumptions: 'Alle offenen Positionen erreichen gleichzeitig ihren initialen Stop (Extremfall, z.B. Markt-weiter Crash) - Summe aller geplanten Risikobetraege.', affected_positions: offenePositionen.map(p => ({ ticker: p.ticker, direction: p.direction, loss: round(-1 * (num(p.risk_amount) || 0), 2) })), estimated_loss: round(-1 * offenePositionen.reduce((s, p) => s + (num(p.risk_amount) || 0), 0), 2), loss_pct_of_portfolio: round((-1 * offenePositionen.reduce((s, p) => s + (num(p.risk_amount) || 0), 0) / MODEL_PORTFOLIO_VALUE) * 100, 3), data_quality: dataQuality, model_version: MODEL_VERSION });

return output.map(o => ({ json: o }));

